begin;

-- Authorial V5 content is compiled for review but remains inactive and unaligned.
-- No student can receive it until separate pedagogical and publication gates pass.
do $seed_question_first_content_v5$
declare
  v_catalog_id uuid;
  v_skill_id uuid;
  v_lesson_id uuid;
  v_set_id uuid;
  v_question_id uuid;
  v_question record;
begin
  select id into v_catalog_id
    from public.learning_curriculum_catalogs
   where code = 'TECESCOLA_CORE' and version = '1.0'
   limit 1;
  if v_catalog_id is null then raise exception 'V5_CONTENT_CATALOG_MISSING'; end if;
  select id into v_skill_id
    from public.learning_curriculum_skills
   where catalog_id = v_catalog_id and code = 'COMPUTING_RECOGNIZE_PHISHING';
  if v_skill_id is null then raise exception 'V5_CONTENT_SKILL_MISSING'; end if;

  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 5, 'Reconhecer phishing e verificar mensagens com segurança', 'Phishing tenta induzir alguém a revelar dados, abrir links ou instalar arquivos. Pode chegar por e-mail, mensagem, rede social, ligação ou QR code. Urgência, prêmio inesperado, endereço estranho e pedido de senha ou código são sinais para parar e verificar; nenhum logotipo, texto bem escrito ou cadeado HTTPS comprova sozinho quem enviou. Nunca compartilhe senhas ou códigos. Use o canal oficial acessado por conta própria e converse com um adulto de confiança.', 'Uma mensagem pode imitar uma escola, jogo, serviço ou pessoa conhecida. Observe quem enviou, o que está pedindo, por qual canal chegou, se há pressão de tempo e para onde o link leva. Esses indícios orientam a cautela, mas não permitem sempre declarar com certeza que a conta foi invadida ou que a mensagem é falsa. Não use o link inesperado para confirmar a própria mensagem. Abra o aplicativo ou endereço oficial por um caminho que você já conhece, ou confirme com a instituição por outro contato. Senhas e códigos de autenticação são segredos: não os envie por mensagem, ligação, QR ou formulário inesperado. Se clicou ou compartilhou algo, pare e conte a um adulto; pedir ajuda rapidamente é melhor do que esconder por vergonha.',
    'Exemplo totalmente fictício: “Sua conta escolar será encerrada hoje. Acesse portal-escola.exemplo e informe sua senha e o código recebido”. Há pelo menos três razões para parar: prazo ameaçador, endereço não reconhecido e pedido de dois segredos. Isso ainda não prova que a escola sofreu uma invasão. Não clique nem responda. Abra o portal escolar pelo endereço salvo ou peça a um adulto para confirmar com a secretaria por um contato já conhecido.', array['Pare quando houver urgência, prêmio inesperado ou pedido de segredo.', 'Nunca compartilhe senha ou código de autenticação, nem com alguém conhecido.', 'Confira o serviço pelo aplicativo ou endereço oficial acessado por conta própria.', 'Se estiver em dúvida ou já tiver informado algo, conte logo a um adulto de confiança.']::text[], 20, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"computing-recognize-phishing","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Reconhecer informações pessoais e privadas.","Usar com mediação um canal digital conhecido."],"key_concepts":["phishing","engenharia social","canal independente","senha","código de autenticação","verificação de origem"],"progression":[{"stage":"FOUNDATION","focus":"Identificar pedido de segredo, urgência e prêmio inesperado como sinais que exigem pausa.","questionIds":["v5-comp-phish-probe-01","v5-comp-phish-probe-02","v5-comp-phish-probe-03","v5-comp-phish-practice-01","v5-comp-phish-practice-02","v5-comp-phish-practice-03"]},{"stage":"APPLICATION","focus":"Comparar remetente, destino, contexto e tipo de informação solicitada sem tratar um sinal isolado como prova.","questionIds":["v5-comp-phish-practice-04","v5-comp-phish-practice-05","v5-comp-phish-practice-06","v5-comp-phish-practice-07","v5-comp-phish-practice-08","v5-comp-phish-practice-09","v5-comp-phish-practice-10","v5-comp-phish-practice-11"]},{"stage":"TRANSFER","focus":"Aplicar verificação independente a mensagens, QR codes, ligações e contas conhecidas.","questionIds":["v5-comp-phish-transfer-01","v5-comp-phish-transfer-02","v5-comp-phish-transfer-03","v5-comp-phish-transfer-04","v5-comp-phish-transfer-05","v5-comp-phish-transfer-06","v5-comp-phish-transfer-07"]},{"stage":"INTEGRATION","focus":"Escolher respostas seguras quando houve clique, exposição de senha ou compartilhamento de código.","questionIds":["v5-comp-phish-lock-01","v5-comp-phish-lock-02","v5-comp-phish-lock-03","v5-comp-phish-lock-04","v5-comp-phish-lock-05"]},{"stage":"SPACED_REVIEW_CANDIDATE","focus":"Revisar a decisão segura em contextos novos; o agendamento depende de mecanismo separado.","questionIds":["v5-comp-phish-review-01","v5-comp-phish-review-02","v5-comp-phish-review-03","v5-comp-phish-review-04","v5-comp-phish-review-05","v5-comp-phish-review-06","v5-comp-phish-review-07","v5-comp-phish-review-08","v5-comp-phish-review-09"]}],"micro_explanations":[{"trigger":"URGENT_OR_UNEXPECTED_MESSAGE","text":"Pressa e surpresa são motivos para pausar e conferir; não são prova isolada de fraude."},{"trigger":"PASSWORD_OR_CODE_REQUEST","text":"Senha e código de autenticação são segredos. Não os envie; confirme o pedido por outro canal."},{"trigger":"LOGO_VOICE_OR_HTTPS_AS_PROOF","text":"Logotipo, voz e cadeado não identificam sozinhos quem controla a conta ou a página."},{"trigger":"CLICKED_WITHOUT_ENTERING_DATA","text":"Pare de interagir, feche a página e conte a um adulto; não teste o formulário nem instale arquivos."},{"trigger":"SECRET_ALREADY_SHARED","text":"Peça ajuda imediatamente e use o serviço oficial para proteger a conta; não esconda por vergonha."}],"remediations":[{"misconception":"URGENCY_REQUIRES_CLICK","prompt":"Retire o botão da mensagem da situação. Qual canal conhecido permite conferir a conta sem obedecer ao prazo enviado?"},{"misconception":"LOGO_PROVES_IDENTITY","prompt":"Compare o nome e a foto com outra informação que só possa ser confirmada por um canal independente."},{"misconception":"HTTPS_EQUALS_OFFICIAL","prompt":"Explique o que uma conexão protegida faz e depois confira quem controla o endereço da página."},{"misconception":"KNOWN_CONTACT_ALWAYS_SAFE","prompt":"Imagine que a conta do contato foi usada por outra pessoa. Como confirmar a conversa fora dela?"},{"misconception":"WAIT_AFTER_SECRET_EXPOSURE","prompt":"Ordene as ações: contar a um adulto, abrir o serviço oficial sem usar o link e pedir ajuda para proteger a conta."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"title":"Dicas Rápidas: E-mails, Golpes e Fraudes","publisher":"CERT.br / NIC.br / CGI.br","url":"https://cartilha.cert.br/dicas-rapidas/","accessedOn":"2026-10-13","supports":["cautela com links e anexos inesperados","verificação de informações e canais oficiais","atenção a urgência e pedidos de dados"],"use":"Fonte de segurança digital para delimitar sinais e ações preventivas. Os exemplos, atividades e itens deste pacote são originais."},{"title":"Ataque Phishing: como identificar tentativas de fraude na internet","publisher":"Ministério das Comunicações","url":"https://www.gov.br/mcom/pt-br/noticias/noticias_alt/2026/julho/ataque-phishing-como-identificar-tentativas-de-fraude-na-internet/","accessedOn":"2026-10-13","supports":["phishing em diferentes canais","urgência e solicitações de dados como sinais de alerta","verificação por endereço oficial acessado diretamente"],"use":"Referência informativa para revisão de escopo. Nenhuma mensagem ou atividade foi copiada; não declara mapeamento BNCC oficial."}],"copyright_note":"Enunciados, alternativas, explicações e atividade são originais e usam situações hipotéticas, sem links ativos nem coleta de dados. As fontes orientam apenas o escopo de segurança. Mapeamento oficial e revisão pedagógica humana não foram aprovados.","authentic_activities":[{"id":"v5-computing-phishing-message-cards","title":"Pausa, conferência e escolha segura","instructions":"Com o professor, analise cartões impressos de mensagens totalmente fictícias: uma promoção inesperada, um aviso com urgência e uma comunicação escolar confirmada em canal conhecido. Marque o que é fato observado, o que é apenas indício e o que ainda precisa ser confirmado. Em cada caso, proponha uma ação segura e um canal independente. Não acesse a internet aberta nem use contas reais.","evidence":"Quadro que separa observação, inferência e informação a confirmar; escolha justificada de canal independente; resposta que protege senhas, códigos e dados pessoais.","privacyGuard":"Usar somente nomes, endereços e mensagens inventados em cartões sem links ativos. Não pedir senha, código, telefone, endereço, foto, conta ou relato de experiência real dos estudantes. Não escanear QR codes, abrir anexos, cadastrar-se ou encaminhar mensagens. Atividade mediada pelo professor.","rubric":[{"criterion":"Leitura dos sinais","emerging":"Segue a urgência ou escolhe pela aparência.","developing":"Identifica um sinal, mas o trata como prova definitiva.","proficient":"Relaciona pedido, contexto e canal, explicando que sinais orientam a cautela sem provar tudo isoladamente."},{"criterion":"Verificação","emerging":"Usa o próprio link ou remetente para confirmar a mensagem.","developing":"Sugere perguntar a alguém, mas pelo mesmo canal suspeito.","proficient":"Escolhe um aplicativo, endereço ou contato oficial acessado independentemente."},{"criterion":"Proteção de dados","emerging":"Aceita enviar senha, código ou dado privado.","developing":"Percebe o risco após uma pergunta orientadora.","proficient":"Mantém os segredos privados e explica por que não os compartilha."},{"criterion":"Resposta e pedido de ajuda","emerging":"Continua interagindo ou esconde o ocorrido.","developing":"Interrompe a interação, mas não sabe a quem recorrer.","proficient":"Para, não encaminha e procura um adulto ou canal de suporte conhecido."}]}],"objective":"Reconhecer sinais de uma tentativa de phishing sem depender de um único indício; pausar, preservar senhas e códigos, verificar a solicitação por canal independente e pedir ajuda quando necessário.","common_mistake":"Achar que um logotipo, uma voz conhecida, a ausência de erros ou o cadeado HTTPS provam a identidade do remetente. Esses elementos podem ser copiados ou não dizem quem controla a página. Também é um erro afirmar que toda mensagem com um link é falsa: verifique origem, destino e contexto por um caminho independente.","estimated_minutes":20}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
  select id into v_lesson_id from public.learning_skill_lessons
   where canonical_skill_id = v_skill_id and version = 5
     and metadata->>'content_id' = 'computing-recognize-phishing' and active = false;
  if v_lesson_id is null then raise exception 'V5_CONTENT_LESSON_CONFLICT'; end if;

  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-comp-phish-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"GAME_BLOCK_ALERT","statement":"Uma mensagem inesperada diz que a conta de jogo será bloqueada em cinco minutos e pede um clique para “confirmar a senha”. Qual é a atitude mais segura?","options":["Parar e conferir a conta pelo aplicativo ou endereço oficial acessado por conta própria, pedindo ajuda se houver dúvida.","Clicar depressa para evitar o bloqueio.","Responder à mensagem com a senha para confirmar que a conta é sua.","Encaminhar o link a colegas para perguntar se funciona."],"correctAnswer":"Parar e conferir a conta pelo aplicativo ou endereço oficial acessado por conta própria, pedindo ajuda se houver dúvida.","explanation":"A urgência e o pedido de senha são sinais de alerta, não uma prova isolada. A mensagem não deve conduzir a verificação: use um canal conhecido e independente.","hint":"A mensagem quer que você aja antes de conferir por outro caminho.","errorFocus":"OBEY_URGENT_CREDENTIAL_REQUEST","misconceptions":{"Clicar depressa para evitar o bloqueio.":["URGENCY_REQUIRES_CLICK"],"Responder à mensagem com a senha para confirmar que a conta é sua.":["PASSWORD_IS_PROOF"],"Encaminhar o link a colegas para perguntar se funciona.":["SPREAD_UNVERIFIED_LINK"]},"position":1},{"id":"v5-comp-phish-probe-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"SELECT","contextFamily":"GAME_REWARD_QR","statement":"Um cartaz desconhecido promete moedas grátis para um jogo e mostra um QR code que abre uma página de login. O que fazer antes de qualquer cadastro?","options":["Ler o QR e entrar, pois cartazes impressos são sempre confiáveis.","Não informar dados; conferir a promoção no aplicativo ou site oficial e conversar com um adulto de confiança.","Usar a senha de um colega para testar a página.","Preencher só o primeiro campo para descobrir se o prêmio existe."],"correctAnswer":"Não informar dados; conferir a promoção no aplicativo ou site oficial e conversar com um adulto de confiança.","explanation":"QR codes também podem levar a páginas falsas. Uma promoção deve ser confirmada por um canal oficial encontrado independentemente, sem compartilhar senhas.","hint":"A aparência do cartaz não confirma quem criou o QR code.","errorFocus":"TRUST_QR_WITHOUT_SOURCE","misconceptions":{"Ler o QR e entrar, pois cartazes impressos são sempre confiáveis.":["PRINTED_MEANS_SAFE"],"Usar a senha de um colega para testar a página.":["BORROW_CREDENTIALS"],"Preencher só o primeiro campo para descobrir se o prêmio existe.":["PARTIAL_ENTRY_IS_SAFE"]},"position":2},{"id":"v5-comp-phish-probe-03","purpose":"PROBE","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"SCHOOL_CODE_DM","statement":"Um perfil com o logotipo da escola pede por mensagem privada o código de seis dígitos recebido no celular. Qual resposta protege melhor a conta?","options":["Enviar o código porque o perfil usa o logotipo correto.","Publicar o código no grupo da turma para todos avaliarem.","Não enviar o código e confirmar a solicitação com a escola por um contato oficial já conhecido, avisando um adulto.","Trocar um dígito e mandar os outros cinco."],"correctAnswer":"Não enviar o código e confirmar a solicitação com a escola por um contato oficial já conhecido, avisando um adulto.","explanation":"Códigos de autenticação são segredos de acesso. Um perfil pode copiar um logotipo ou estar comprometido; confirme a solicitação por outro canal.","hint":"O código funciona como uma chave temporária da conta.","errorFocus":"SHARE_AUTHENTICATION_CODE","misconceptions":{"Enviar o código porque o perfil usa o logotipo correto.":["LOGO_PROVES_IDENTITY"],"Publicar o código no grupo da turma para todos avaliarem.":["PUBLIC_SHARING_CHECK"],"Trocar um dígito e mandar os outros cinco.":["PARTIAL_CODE_SHARING"]},"position":3},{"id":"v5-comp-phish-practice-01","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"COMPARE","contextFamily":"LOOKALIKE_SENDER","statement":"Chega um aviso de “atualização escolar” de um endereço que troca uma letra no nome usado pela escola. O aviso contém o logotipo correto e um botão de acesso. Qual decisão é mais cuidadosa?","options":["Confiar no botão porque o logotipo parece verdadeiro.","Responder pedindo que enviem uma senha provisória.","Apagar todos os avisos da escola sem verificar o assunto.","Não usar o botão; conferir o aviso no portal conhecido ou perguntar à escola por um contato salvo."],"correctAnswer":"Não usar o botão; conferir o aviso no portal conhecido ou perguntar à escola por um contato salvo.","explanation":"Uma diferença pequena no remetente merece conferência, mas não permite concluir sozinha quem enviou. O canal independente ajuda a validar o aviso.","hint":"Compare o remetente com um endereço oficial que você já conhece.","errorFocus":"TRUST_LOOKALIKE_SENDER","misconceptions":{"Confiar no botão porque o logotipo parece verdadeiro.":["LOGO_OVERRIDES_SENDER"],"Responder pedindo que enviem uma senha provisória.":["REQUEST_MORE_SECRETS"],"Apagar todos os avisos da escola sem verificar o assunto.":["REJECT_ALL_MESSAGES"]},"position":1},{"id":"v5-comp-phish-practice-02","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"PRIZE_PASSWORD","statement":"Uma página promete um prêmio inesperado e pede a senha do e-mail para “comprovar a identidade”. Qual sinal exige parar?","options":["O pedido de senha: ela não deve ser entregue para receber um prêmio.","A página usar cores alegres.","O prêmio aparecer em uma ilustração.","O formulário ter apenas dois campos."],"correctAnswer":"O pedido de senha: ela não deve ser entregue para receber um prêmio.","explanation":"Senha é informação secreta. Um prêmio não justifica enviá-la; confirme a promoção em um canal oficial sem usar o link recebido.","hint":"Qual dado permite que outra pessoa entre na conta?","errorFocus":"PASSWORD_FOR_REWARD","misconceptions":{"A página usar cores alegres.":["COLOR_AS_TRUST_SIGNAL"],"O prêmio aparecer em uma ilustração.":["IMAGE_AS_VERIFICATION"],"O formulário ter apenas dois campos.":["SHORT_FORM_IS_SAFE"]},"position":2},{"id":"v5-comp-phish-practice-03","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"APPLY","contextFamily":"FRIEND_LOGIN_CODE","statement":"Um colega conhecido manda: “me envie o código que chegou aí para eu recuperar meu jogo”. O que é mais seguro?","options":["Enviar porque a mensagem veio de um contato conhecido.","Não enviar o código; confirmar com o colega por outro meio e avisar um adulto, pois a conta dele pode não estar sob controle dele.","Mandar o código e depois pedir que ele apague a conversa.","Enviar uma captura de tela em vez de copiar o código."],"correctAnswer":"Não enviar o código; confirmar com o colega por outro meio e avisar um adulto, pois a conta dele pode não estar sob controle dele.","explanation":"Contas conhecidas também podem ser usadas por outra pessoa. Códigos de acesso não devem ser compartilhados; confirme separadamente.","hint":"Ter o nome de um colega na tela não prova quem está digitando.","errorFocus":"TRUST_COMPROMISED_CONTACT","misconceptions":{"Enviar porque a mensagem veio de um contato conhecido.":["KNOWN_CONTACT_ALWAYS_SAFE"],"Mandar o código e depois pedir que ele apague a conversa.":["DELETE_AFTER_SHARING"],"Enviar uma captura de tela em vez de copiar o código.":["SCREENSHOT_IS_NOT_SHARING"]},"position":3},{"id":"v5-comp-phish-practice-04","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"PLAN","contextFamily":"SHORT_PRIZE_LINK","statement":"Uma mensagem encurta o endereço de uma promoção e diz que o prêmio acaba hoje. Qual plano é mais seguro?","options":["Abrir em uma aba anônima, pois isso confirma que o link é seguro.","Encaminhar o link para várias pessoas verificarem clicando.","Não abrir o link recebido; procurar a promoção no canal oficial acessado por conta própria e pedir ajuda se necessário.","Digitar a senha primeiro e conferir a promoção depois."],"correctAnswer":"Não abrir o link recebido; procurar a promoção no canal oficial acessado por conta própria e pedir ajuda se necessário.","explanation":"Um endereço encurtado esconde o destino e a pressa reduz o tempo para avaliar. Navegação anônima não verifica a origem do link.","hint":"Escolha uma forma de conferir sem usar o endereço da mensagem.","errorFocus":"SHORT_LINK_UNDER_PRESSURE","misconceptions":{"Abrir em uma aba anônima, pois isso confirma que o link é seguro.":["PRIVATE_BROWSING_PROVES_SAFETY"],"Encaminhar o link para várias pessoas verificarem clicando.":["CROWD_CLICKING_VERIFICATION"],"Digitar a senha primeiro e conferir a promoção depois.":["CREDENTIALS_BEFORE_VERIFICATION"]},"position":4},{"id":"v5-comp-phish-practice-05","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"UNEXPECTED_ATTACHMENT","statement":"Chega um arquivo inesperado de um endereço que você não reconhece, com o assunto “atividade da turma”. Ainda não há confirmação do professor. O que fazer?","options":["Abrir porque o assunto menciona a turma.","Baixar em outro dispositivo para testar se está tudo bem.","Responder com seus dados para perguntar se o arquivo é seu.","Não abrir nem baixar por enquanto; confirmar com o professor por um canal escolar que você já usa."],"correctAnswer":"Não abrir nem baixar por enquanto; confirmar com o professor por um canal escolar que você já usa.","explanation":"O assunto pode ser copiado. Anexos inesperados devem ser verificados por um canal independente antes de abrir.","hint":"Confirme com a pessoa que poderia ter enviado, mas sem responder ao remetente desconhecido.","errorFocus":"OPEN_UNEXPECTED_ATTACHMENT","misconceptions":{"Abrir porque o assunto menciona a turma.":["SCHOOL_TOPIC_PROVES_SOURCE"],"Baixar em outro dispositivo para testar se está tudo bem.":["SECOND_DEVICE_MAKES_FILE_SAFE"],"Responder com seus dados para perguntar se o arquivo é seu.":["REPLY_WITH_PERSONAL_DATA"]},"position":5},{"id":"v5-comp-phish-practice-06","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"HTTPS_FAKE_PORTAL","statement":"Uma página com cadeado no navegador imita o portal escolar, mas foi aberta por um link inesperado. O cadeado, sozinho, prova que a página pertence à escola?","options":["Não. O cadeado indica uma conexão protegida, mas não confirma a identidade da página; acesse o portal pelo endereço conhecido.","Sim; toda página com cadeado é oficial.","Sim, desde que a página também mostre o logotipo.","Não; nenhum portal escolar pode usar conexão protegida."],"correctAnswer":"Não. O cadeado indica uma conexão protegida, mas não confirma a identidade da página; acesse o portal pelo endereço conhecido.","explanation":"HTTPS protege a conexão com o site aberto, mas não prova que o site seja a instituição correta. Confira o endereço e use um caminho independente.","hint":"Pense no que a conexão protege e no que ela não identifica.","errorFocus":"HTTPS_AS_IDENTITY_PROOF","misconceptions":{"Sim; toda página com cadeado é oficial.":["HTTPS_EQUALS_OFFICIAL"],"Sim, desde que a página também mostre o logotipo.":["HTTPS_AND_LOGO_PROVE_SOURCE"],"Não; nenhum portal escolar pode usar conexão protegida.":["HTTPS_NEVER_USED"]},"position":6},{"id":"v5-comp-phish-practice-07","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"VERIFY","contextFamily":"EVENT_QR_POSTER","statement":"Um cartaz de evento no corredor tem um QR code para inscrição, mas não informa quem organizou. Como verificar sem arriscar dados?","options":["Escanear e preencher tudo porque o cartaz está dentro da escola.","Perguntar à escola por um canal conhecido e confirmar se aquele cartaz e endereço são oficiais antes de preencher qualquer dado.","Usar o QR e inserir só o nome completo para testar.","Pedir a um colega para informar a senha dele no formulário."],"correctAnswer":"Perguntar à escola por um canal conhecido e confirmar se aquele cartaz e endereço são oficiais antes de preencher qualquer dado.","explanation":"Um cartaz pode ser substituído ou alterado. Confirme autoria e destino com a organização por um canal independente antes de inserir informações.","hint":"O local do cartaz não garante quem o colocou.","errorFocus":"TRUST_UNVERIFIED_EVENT_QR","misconceptions":{"Escanear e preencher tudo porque o cartaz está dentro da escola.":["LOCATION_PROVES_POSTER"],"Usar o QR e inserir só o nome completo para testar.":["NAME_ONLY_IS_HARMLESS"],"Pedir a um colega para informar a senha dele no formulário.":["PEER_CREDENTIAL_TEST"]},"position":7},{"id":"v5-comp-phish-practice-08","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"SELECT","contextFamily":"SECRET_URGENT_REQUEST","statement":"Uma mensagem diz “não conte a ninguém, responda agora com seu código para não perder o acesso”. Qual ação enfrenta melhor essa pressão?","options":["Obedecer ao pedido de segredo para proteger a conta.","Mandar o código para ganhar tempo e trocar a senha depois.","Não responder nem enviar o código; mostrar a mensagem a um adulto e confirmar por um canal oficial conhecido.","Perguntar ao próprio remetente se a solicitação é verdadeira."],"correctAnswer":"Não responder nem enviar o código; mostrar a mensagem a um adulto e confirmar por um canal oficial conhecido.","explanation":"Segredo e urgência podem ser usados para impedir uma conferência. Pare, não envie códigos e procure ajuda em um canal diferente.","hint":"A mensagem está tentando impedir você de consultar alguém.","errorFocus":"SECRECY_AND_URGENCY_PRESSURE","misconceptions":{"Obedecer ao pedido de segredo para proteger a conta.":["SECRECY_MEANS_LEGITIMATE"],"Mandar o código para ganhar tempo e trocar a senha depois.":["TEMPORARY_SHARING"],"Perguntar ao próprio remetente se a solicitação é verdadeira.":["SENDER_SELF_VERIFICATION"]},"position":8},{"id":"v5-comp-phish-practice-09","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"DISTINGUISH","contextFamily":"FAKE_GAME_SUPPORT","statement":"Um perfil chamado “suporte do jogo” diz que pode recuperar uma conta se você enviar sua senha por mensagem. Qual conclusão é mais responsável?","options":["Enviar a senha se o perfil souber o nome do jogo.","Enviar uma senha antiga que não usa mais.","Pedir ao perfil que mande primeiro uma senha de exemplo.","O pedido é inseguro; não enviar a senha e procurar o suporte dentro do aplicativo ou site oficial, com ajuda de um adulto."],"correctAnswer":"O pedido é inseguro; não enviar a senha e procurar o suporte dentro do aplicativo ou site oficial, com ajuda de um adulto.","explanation":"Conhecer o jogo não autentica o perfil. Use o suporte acessado por um caminho oficial e nunca compartilhe a senha por mensagem.","hint":"O canal de suporte deve ser encontrado sem seguir o contato suspeito.","errorFocus":"PASSWORD_TO_IMPERSONATED_SUPPORT","misconceptions":{"Enviar a senha se o perfil souber o nome do jogo.":["KNOWS_GAME_PROVES_SUPPORT"],"Enviar uma senha antiga que não usa mais.":["OLD_PASSWORD_IS_SAFE"],"Pedir ao perfil que mande primeiro uma senha de exemplo.":["SENDER_PROOF_REQUEST"]},"position":9},{"id":"v5-comp-phish-practice-10","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"NEW_DEVICE_ALERT","statement":"Você recebe um alerta de “novo acesso” com um link para revisar a conta. Pode ser um aviso verdadeiro ou falso. Qual ação evita confiar no link?","options":["Abrir o aplicativo ou endereço oficial por conta própria e verificar a atividade; se não entender o alerta, pedir ajuda a um adulto.","Clicar no link porque alertas de segurança são sempre verdadeiros.","Responder ao remetente com o código de autenticação.","Ignorar para sempre, mesmo se o aplicativo oficial mostrar um acesso desconhecido."],"correctAnswer":"Abrir o aplicativo ou endereço oficial por conta própria e verificar a atividade; se não entender o alerta, pedir ajuda a um adulto.","explanation":"Alertas podem ser falsificados ou legítimos. Verifique a atividade no serviço acessado independentemente e procure ajuda diante de algo desconhecido.","hint":"A mensagem não deve ser o único caminho para verificar a própria mensagem.","errorFocus":"ALERT_LINK_AS_ONLY_CHECK","misconceptions":{"Clicar no link porque alertas de segurança são sempre verdadeiros.":["SECURITY_LABEL_PROVES_SOURCE"],"Responder ao remetente com o código de autenticação.":["AUTH_CODE_TO_ALERT_SENDER"],"Ignorar para sempre, mesmo se o aplicativo oficial mostrar um acesso desconhecido.":["IGNORE_ALL_ALERTS"]},"position":10},{"id":"v5-comp-phish-practice-11","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"PROTECT","contextFamily":"GIVEAWAY_PERSONAL_DATA","statement":"Uma promoção por mensagem pede data de nascimento, foto e nome completo para liberar um sorteio. O que fazer?","options":["Enviar a foto, mas cobrir os olhos.","Não enviar esses dados; conversar com um adulto e conferir se a promoção existe em um canal oficial, sem usar o link recebido.","Informar os dados se o prêmio parecer adequado à idade.","Pedir a um amigo que participe com os próprios dados."],"correctAnswer":"Não enviar esses dados; conversar com um adulto e conferir se a promoção existe em um canal oficial, sem usar o link recebido.","explanation":"Dados pessoais não devem ser entregues a uma promoção inesperada. A aparência do prêmio não valida o pedido nem o destino dos dados.","hint":"A pergunta não é só se o prêmio parece bom, mas quem receberia suas informações.","errorFocus":"PERSONAL_DATA_FOR_GIVEAWAY","misconceptions":{"Enviar a foto, mas cobrir os olhos.":["PARTIAL_IMAGE_PROTECTION"],"Informar os dados se o prêmio parecer adequado à idade.":["PRIZE_VALUE_JUSTIFIES_DATA"],"Pedir a um amigo que participe com os próprios dados.":["TRANSFER_RISK_TO_FRIEND"]},"position":11},{"id":"v5-comp-phish-transfer-01","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"INFER","contextFamily":"COUSIN_COMPROMISED_ACCOUNT","statement":"Uma conta de parente manda um endereço estranho e diz “abre sem perguntar”. Você não sabe se foi mesmo o parente. O que fazer?","options":["Abrir porque a conta já está salva nos contatos.","Mandar o endereço para mais parentes clicarem.","Não abrir ainda; confirmar com o parente por outro meio já conhecido e pedir ajuda se continuar em dúvida.","Responder com uma senha para provar que é da família."],"correctAnswer":"Não abrir ainda; confirmar com o parente por outro meio já conhecido e pedir ajuda se continuar em dúvida.","explanation":"Uma conta conhecida também pode ter sido acessada por outra pessoa. Verifique fora daquela conversa antes de abrir o endereço.","hint":"Mude de canal para confirmar quem está falando.","errorFocus":"KNOWN_ACCOUNT_COMPROMISE","misconceptions":{"Abrir porque a conta já está salva nos contatos.":["SAVED_CONTACT_PROVES_SENDER"],"Mandar o endereço para mais parentes clicarem.":["FAMILY_FORWARDING_CHECK"],"Responder com uma senha para provar que é da família.":["PASSWORD_AS_IDENTITY_PROOF"]},"position":1},{"id":"v5-comp-phish-transfer-02","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"PLAN","contextFamily":"ENROLLMENT_CANCEL_NOTICE","statement":"Uma mensagem afirma que sua matrícula será cancelada hoje e aponta para um endereço diferente do portal usado pela escola. Qual é o próximo passo?","options":["Preencher o formulário para evitar o cancelamento.","Responder com nome, turma e senha para confirmar a matrícula.","Ignorar qualquer aviso escolar, inclusive no portal oficial.","Não usar o link; entrar no portal pelo endereço já conhecido e perguntar à escola por um contato oficial."],"correctAnswer":"Não usar o link; entrar no portal pelo endereço já conhecido e perguntar à escola por um contato oficial.","explanation":"A ameaça de cancelamento cria urgência. Confira o status por um canal escolar conhecido; não é necessário confiar no endereço recebido.","hint":"Procure a informação diretamente no canal que a escola já utiliza.","errorFocus":"SCHOOL_CANCELLATION_PRESSURE","misconceptions":{"Preencher o formulário para evitar o cancelamento.":["FEAR_DRIVES_FORM_ENTRY"],"Responder com nome, turma e senha para confirmar a matrícula.":["IDENTITY_DETAILS_TO_SENDER"],"Ignorar qualquer aviso escolar, inclusive no portal oficial.":["ALL_NOTICES_ARE_FAKE"]},"position":2},{"id":"v5-comp-phish-transfer-03","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"VERIFY","contextFamily":"LIBRARY_EVENT_QR","statement":"Na biblioteca há um QR code para reservar um livro. A escola costuma organizar reservas digitais, mas você não reconhece o cartaz. Qual decisão evita tanto confiar cegamente quanto rejeitar tudo?","options":["Confirmar com a biblioteca por um canal conhecido que o cartaz e o destino do QR são os usados pela escola antes de informar dados.","Escanear sem conferir, pois a atividade parece escolar.","Nunca usar QR codes, mesmo quando a biblioteca confirmar o serviço.","Digitar a senha escolar no primeiro formulário para testar."],"correctAnswer":"Confirmar com a biblioteca por um canal conhecido que o cartaz e o destino do QR são os usados pela escola antes de informar dados.","explanation":"QR code é apenas uma forma de abrir um destino; pode ser legítimo ou não. A confirmação independente avalia o contexto sem exigir rejeitar todo recurso digital.","hint":"Confirme a origem e o destino antes de qualquer login.","errorFocus":"QR_WITHOUT_CONTEXT_CHECK","misconceptions":{"Escanear sem conferir, pois a atividade parece escolar.":["SCHOOL_CONTEXT_IS_PROOF"],"Nunca usar QR codes, mesmo quando a biblioteca confirmar o serviço.":["QR_ALWAYS_UNSAFE"],"Digitar a senha escolar no primeiro formulário para testar.":["LOGIN_AS_TEST"]},"position":3},{"id":"v5-comp-phish-transfer-04","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"PHONE_TECH_SUPPORT","statement":"Uma ligação diz ser da equipe de tecnologia da escola e pede o código que acabou de chegar para “impedir uma invasão”. O que fazer?","options":["Ler o código porque a ligação menciona uma invasão.","Não dizer o código; encerrar a solicitação e contatar a escola pelo telefone ou canal oficial já conhecido, com ajuda de um adulto.","Dizer apenas os três primeiros números.","Pedir que a pessoa confirme seu nome completo e depois obedecer."],"correctAnswer":"Não dizer o código; encerrar a solicitação e contatar a escola pelo telefone ou canal oficial já conhecido, com ajuda de um adulto.","explanation":"Um pedido de código continua inseguro mesmo quando a pessoa usa uma explicação convincente. Faça a verificação pelo contato oficial que você já tinha.","hint":"Quem ligou não deve fornecer o único caminho para confirmar a ligação.","errorFocus":"VOICE_CALL_CODE_REQUEST","misconceptions":{"Ler o código porque a ligação menciona uma invasão.":["THREAT_AUTHENTICATES_CALLER"],"Dizer apenas os três primeiros números.":["PARTIAL_CODE_SHARING"],"Pedir que a pessoa confirme seu nome completo e depois obedecer.":["PERSONAL_DETAILS_VERIFY_CALLER"]},"position":4},{"id":"v5-comp-phish-transfer-05","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"SELECT","contextFamily":"PAYMENT_MESSAGE_TO_STUDENT","statement":"Uma mensagem diz que há um problema no pagamento escolar e pede que o estudante envie o endereço de casa para “ajudar o responsável”. O que é mais seguro?","options":["Enviar o endereço, pois a mensagem trata de pagamento.","Mandar o endereço de um colega para comparar.","Não enviar o endereço; falar com o responsável por um meio conhecido e pedir que ele confira a informação com a escola.","Responder perguntando qual cartão o responsável usa."],"correctAnswer":"Não enviar o endereço; falar com o responsável por um meio conhecido e pedir que ele confira a informação com a escola.","explanation":"Endereço e dados financeiros são privados. O estudante pode confirmar a mensagem com seu responsável sem revelar informações ao remetente.","hint":"Use um contato que já seja conhecido, fora da conversa inesperada.","errorFocus":"PERSONAL_ADDRESS_REQUEST","misconceptions":{"Enviar o endereço, pois a mensagem trata de pagamento.":["TOPIC_JUSTIFIES_ADDRESS"],"Mandar o endereço de um colega para comparar.":["THIRD_PARTY_DATA_TEST"],"Responder perguntando qual cartão o responsável usa.":["REQUEST_MORE_FINANCIAL_DATA"]},"position":5},{"id":"v5-comp-phish-transfer-06","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"PLAN","contextFamily":"TEACHER_VOICE_NOTE","statement":"Uma mensagem de voz parece ser do professor e pede para trocar a senha em um link enviado depois. Como agir?","options":["Seguir porque a voz parece conhecida.","Enviar a senha atual para o professor confirmar a conta.","Pedir a colegas que usem o link e contem o resultado.","Não seguir o link ainda; confirmar com o professor pela plataforma escolar conhecida ou com a secretaria, e pedir apoio a um adulto."],"correctAnswer":"Não seguir o link ainda; confirmar com o professor pela plataforma escolar conhecida ou com a secretaria, e pedir apoio a um adulto.","explanation":"Uma voz ou nome conhecido pode ser imitado ou usado por outra pessoa. Confirme o pedido por um canal escolar independente e não envie a senha.","hint":"Reconhecer a voz não confirma o link nem a autoria da mensagem posterior.","errorFocus":"VOICE_IMPERSONATION_TRUST","misconceptions":{"Seguir porque a voz parece conhecida.":["VOICE_MATCH_PROVES_IDENTITY"],"Enviar a senha atual para o professor confirmar a conta.":["PASSWORD_TO_TEACHER"],"Pedir a colegas que usem o link e contem o resultado.":["CLASSMATES_AS_TESTERS"]},"position":6},{"id":"v5-comp-phish-transfer-07","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"SCHOLARSHIP_CREDENTIAL_FORM","statement":"Um formulário de bolsa chega por mensagem e pede a senha do portal escolar e fotos de documentos antes de explicar quem organiza a seleção. Qual ação é melhor?","options":["Não preencher; consultar um adulto e localizar a instituição organizadora por um canal oficial independente para confirmar o processo e os dados necessários.","Preencher porque bolsas costumam ter prazo.","Mandar primeiro a senha e guardar as fotos para depois.","Enviar documentos no grupo da turma para votar se parecem verdadeiros."],"correctAnswer":"Não preencher; consultar um adulto e localizar a instituição organizadora por um canal oficial independente para confirmar o processo e os dados necessários.","explanation":"A solicitação reúne dados sensíveis e não identifica claramente o responsável. Confirme a organização e o processo antes de compartilhar qualquer documento.","hint":"Descubra quem é responsável sem usar os contatos fornecidos pela própria mensagem.","errorFocus":"UNKNOWN_ORGANIZER_SENSITIVE_DATA","misconceptions":{"Preencher porque bolsas costumam ter prazo.":["DEADLINE_PROVES_LEGITIMACY"],"Mandar primeiro a senha e guardar as fotos para depois.":["PASSWORD_FIRST"],"Enviar documentos no grupo da turma para votar se parecem verdadeiros.":["PUBLIC_DOCUMENT_REVIEW"]},"position":7},{"id":"v5-comp-phish-lock-01","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"RESPOND","contextFamily":"CLICKED_NO_DATA","statement":"Você abriu um link suspeito, mas não digitou nada nem baixou arquivo. Qual atitude é mais apropriada agora?","options":["Digitar dados falsos para testar o formulário.","Fechar a página, não continuar interagindo e contar a um adulto para avaliar a mensagem e usar os canais oficiais se necessário.","Voltar ao link e procurar o botão de sair da promoção.","Apagar o histórico e esconder o ocorrido de todos."],"correctAnswer":"Fechar a página, não continuar interagindo e contar a um adulto para avaliar a mensagem e usar os canais oficiais se necessário.","explanation":"Abrir um link não significa automaticamente que houve roubo de dados, mas é prudente parar e pedir ajuda. Não preencha nem baixe nada.","hint":"A prioridade é interromper a interação, não testar a página.","errorFocus":"CONTINUE_AFTER_SUSPICIOUS_CLICK","misconceptions":{"Digitar dados falsos para testar o formulário.":["FALSE_DATA_AS_TEST"],"Voltar ao link e procurar o botão de sair da promoção.":["CONTINUE_INTERACTION"],"Apagar o histórico e esconder o ocorrido de todos.":["HIDE_INCIDENT"]},"position":1},{"id":"v5-comp-phish-lock-02","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"SEQUENCE","contextFamily":"PASSWORD_ENTERED","statement":"Uma estudante digitou a senha em uma página que agora parece falsa. Qual sequência reduz melhor o risco?","options":["Responder à página falsa perguntando se recebeu a senha.","Esperar para ver se alguém entra antes de contar a alguém.","Avisar imediatamente um adulto; acessar o serviço pelo canal oficial e trocar a senha; pedir ajuda ao suporte oficial e revisar outras contas que usam a mesma senha.","Trocar somente o nome de perfil e continuar usando a mesma senha."],"correctAnswer":"Avisar imediatamente um adulto; acessar o serviço pelo canal oficial e trocar a senha; pedir ajuda ao suporte oficial e revisar outras contas que usam a mesma senha.","explanation":"A senha pode ter sido exposta. Um adulto pode ajudar a acessar o serviço correto, trocar credenciais e verificar outras contas sem voltar à página suspeita.","hint":"Não volte ao link; use o aplicativo ou endereço oficial acessado separadamente.","errorFocus":"DELAY_AFTER_PASSWORD_EXPOSURE","misconceptions":{"Responder à página falsa perguntando se recebeu a senha.":["ASK_SUSPECTED_PAGE"],"Esperar para ver se alguém entra antes de contar a alguém.":["DELAY_REPORTING"],"Trocar somente o nome de perfil e continuar usando a mesma senha.":["USERNAME_CHANGE_ONLY"]},"position":2},{"id":"v5-comp-phish-lock-03","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"PLAN","contextFamily":"AUTH_CODE_SHARED","statement":"Você enviou um código de autenticação e percebeu que talvez fosse uma fraude. O que fazer primeiro?","options":["Apagar a conversa e esperar que o código expire.","Enviar um segundo código para cancelar o primeiro.","Culpar e bloquear a pessoa sem avisar o serviço.","Contar imediatamente a um adulto e contatar o serviço pelo canal oficial para proteger a conta e encerrar acessos desconhecidos, se essa opção existir."],"correctAnswer":"Contar imediatamente a um adulto e contatar o serviço pelo canal oficial para proteger a conta e encerrar acessos desconhecidos, se essa opção existir.","explanation":"Um código compartilhado pode permitir acesso. É importante pedir ajuda rapidamente e proteger a conta pelo serviço verdadeiro; não é motivo para culpa ou vergonha.","hint":"Aja pelo serviço oficial, não pela conversa que pediu o código.","errorFocus":"NO_RESPONSE_AFTER_CODE_EXPOSURE","misconceptions":{"Apagar a conversa e esperar que o código expire.":["WAIT_FOR_EXPIRATION"],"Enviar um segundo código para cancelar o primeiro.":["SECOND_CODE_CANCELLATION"],"Culpar e bloquear a pessoa sem avisar o serviço.":["BLAME_WITHOUT_ACCOUNT_ACTION"]},"position":3},{"id":"v5-comp-phish-lock-04","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"CHOOSE","contextFamily":"FRIEND_FORWARDS_LINK","statement":"Um colega encaminha uma mensagem suspeita para o grupo da turma. Qual resposta reduz a propagação e protege os colegas?","options":["Não encaminhar nem abrir; avisar o colega em particular por um meio conhecido e pedir que um adulto ou a plataforma reporte a mensagem.","Reencaminhar com “cuidado” para todos os contatos.","Abrir para descobrir se os outros devem se preocupar.","Publicar o número e o perfil do remetente para que todos ataquem a conta."],"correctAnswer":"Não encaminhar nem abrir; avisar o colega em particular por um meio conhecido e pedir que um adulto ou a plataforma reporte a mensagem.","explanation":"Repassar pode espalhar o link ou expor dados. A comunicação privada e o reporte por canais apropriados permitem pedir ajuda sem ampliar o alcance.","hint":"Não transforme uma mensagem suspeita em uma mensagem viral.","errorFocus":"FORWARDING_SUSPICIOUS_MESSAGE","misconceptions":{"Reencaminhar com “cuidado” para todos os contatos.":["WARNING_FORWARD_SPREAD"],"Abrir para descobrir se os outros devem se preocupar.":["CLICK_TO_CLASSIFY"],"Publicar o número e o perfil do remetente para que todos ataquem a conta.":["PUBLIC_SHAMING"]},"position":4},{"id":"v5-comp-phish-lock-05","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"COUNTDOWN_INSTALL_PROMPT","statement":"Uma página aberta por mensagem mostra uma contagem regressiva e pede instalar um “módulo de proteção” para evitar o bloqueio. O que fazer?","options":["Instalar antes que o tempo acabe.","Não instalar; fechar a página e pedir ajuda a um adulto, verificando a conta pelo aplicativo ou endereço oficial.","Desativar as proteções do aparelho para concluir a instalação.","Compartilhar o arquivo no grupo para descobrir se é seguro."],"correctAnswer":"Não instalar; fechar a página e pedir ajuda a um adulto, verificando a conta pelo aplicativo ou endereço oficial.","explanation":"Uma contagem regressiva pode pressionar a pessoa a instalar um arquivo. Não instale programas enviados por uma página inesperada; confirme por um canal oficial.","hint":"A pressão de tempo não é uma razão para instalar algo desconhecido.","errorFocus":"INSTALL_UNEXPECTED_PROTECTION_FILE","misconceptions":{"Instalar antes que o tempo acabe.":["COUNTDOWN_REQUIRES_INSTALL"],"Desativar as proteções do aparelho para concluir a instalação.":["DISABLE_SECURITY"],"Compartilhar o arquivo no grupo para descobrir se é seguro.":["DISTRIBUTE_UNKNOWN_FILE"]},"position":5},{"id":"v5-comp-phish-review-01","purpose":"REVIEW","difficulty":"EASY","cognitiveProcess":"EVALUATE","contextFamily":"KNOWN_SENDER_NO_PROOF","statement":"Uma mensagem tem o nome e a foto de uma pessoa conhecida, mas pede um código de acesso. Qual afirmação é mais correta?","options":["Nome e foto provam que a pessoa está conversando.","O código pode ser enviado se a pessoa for da família.","A identidade exibida não basta para confirmar quem enviou; não compartilhe o código e confirme por outro meio.","É seguro mandar o código e pedir para apagar depois."],"correctAnswer":"A identidade exibida não basta para confirmar quem enviou; não compartilhe o código e confirme por outro meio.","explanation":"Perfis podem ser falsos ou comprometidos. Códigos de acesso devem permanecer privados, mesmo quando o nome parece familiar.","hint":"Confira a pessoa sem usar a conversa que fez o pedido.","errorFocus":"TRUST_PROFILE_IDENTITY","misconceptions":{"Nome e foto provam que a pessoa está conversando.":["PROFILE_IMAGE_PROVES_IDENTITY"],"O código pode ser enviado se a pessoa for da família.":["FAMILY_EXCEPTION"],"É seguro mandar o código e pedir para apagar depois.":["DELETE_AFTER_CODE"]},"position":1},{"id":"v5-comp-phish-review-02","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"DISTINGUISH","contextFamily":"NO_LINK_CODE_REQUEST","statement":"Uma mensagem não tem link, mas pede o código de autenticação para “confirmar sua inscrição”. Ainda pode ser perigosa?","options":["Não; sem link não existe tentativa de phishing.","Não; códigos servem para serem enviados a quem pede.","Sim, então envie o código para o adulto que encaminhou a mensagem.","Sim. Pedir um segredo de acesso é um sinal de risco mesmo sem link; não envie o código e confirme pelo serviço oficial."],"correctAnswer":"Sim. Pedir um segredo de acesso é um sinal de risco mesmo sem link; não envie o código e confirme pelo serviço oficial.","explanation":"Phishing pode ocorrer por conversa, ligação ou outros meios; não depende de um link. Proteja o código e verifique a solicitação independentemente.","hint":"Observe o dado pedido, além de procurar um link.","errorFocus":"LINK_REQUIRED_MISCONCEPTION","misconceptions":{"Não; sem link não existe tentativa de phishing.":["PHISHING_REQUIRES_LINK"],"Não; códigos servem para serem enviados a quem pede.":["CODE_SHARING_NORMAL"],"Sim, então envie o código para o adulto que encaminhou a mensagem.":["FORWARDED_CODE_SAFE"]},"position":2},{"id":"v5-comp-phish-review-03","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"PERFECT_GRAMMAR_MESSAGE","statement":"Uma mensagem está bem escrita, tem o logotipo da escola e pede atualização urgente da senha em um endereço que você não conhece. O que a boa escrita permite concluir?","options":["Nada sobre a legitimidade por si só; não use o endereço recebido e confirme o pedido pelo portal ou contato escolar conhecido.","Que a mensagem é oficial porque não tem erros.","Que a mensagem é falsa com certeza, sem precisar verificar.","Que o logotipo confirma o remetente."],"correctAnswer":"Nada sobre a legitimidade por si só; não use o endereço recebido e confirme o pedido pelo portal ou contato escolar conhecido.","explanation":"Erros ou urgência podem ser sinais, mas sua ausência não prova que a mensagem é legítima. Verifique por um canal independente.","hint":"Um sinal isolado não é um certificado de autenticidade.","errorFocus":"GRAMMAR_AS_AUTHENTICATION","misconceptions":{"Que a mensagem é oficial porque não tem erros.":["GRAMMAR_PROVES_SOURCE"],"Que a mensagem é falsa com certeza, sem precisar verificar.":["ONE_SIGN_PROVES_FRAUD"],"Que o logotipo confirma o remetente.":["LOGO_PROVES_SOURCE"]},"position":3},{"id":"v5-comp-phish-review-04","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EXPLAIN","contextFamily":"HTTPS_LOCK_ICON","statement":"Você vê o cadeado e “https” em uma página aberta por um anúncio inesperado. Qual explicação separa corretamente conexão e identidade?","options":["O cadeado certifica que a instituição enviou o anúncio.","A conexão pode estar protegida, mas isso não prova que o site seja da instituição; confirme o domínio e acesse o canal oficial por conta própria.","O https garante que a página não coleta informações.","A página é falsa porque sites verdadeiros não usam anúncios."],"correctAnswer":"A conexão pode estar protegida, mas isso não prova que o site seja da instituição; confirme o domínio e acesse o canal oficial por conta própria.","explanation":"HTTPS protege a comunicação entre navegador e página, não valida automaticamente quem opera a página nem o anúncio que levou até ela.","hint":"Pergunte o que o cadeado protege e o que ele não verifica.","errorFocus":"CONFUSE_CONNECTION_WITH_IDENTITY","misconceptions":{"O cadeado certifica que a instituição enviou o anúncio.":["LOCK_ICON_CERTIFIES_SENDER"],"O https garante que a página não coleta informações.":["HTTPS_NO_DATA_COLLECTION"],"A página é falsa porque sites verdadeiros não usam anúncios.":["ADS_ALWAYS_FRAUD"]},"position":4},{"id":"v5-comp-phish-review-05","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"VERIFY","contextFamily":"QR_SOURCE_CHECK","statement":"Você encontra um QR code para um formulário de clube escolar. O uso de QR code torna o formulário falso?","options":["Sim; todo QR code é malicioso.","Não; qualquer formulário com brasão escolar é seguro.","Não necessariamente; confirme com o clube ou a escola por um canal conhecido e confira o destino antes de inserir qualquer informação.","Não; preencha primeiro e pergunte depois."],"correctAnswer":"Não necessariamente; confirme com o clube ou a escola por um canal conhecido e confira o destino antes de inserir qualquer informação.","explanation":"O QR code é apenas um meio de abrir um endereço. Avalie a origem e o destino; não precisa concluir que todo QR é falso nem confiar sem verificar.","hint":"Evite tanto a certeza automática quanto a rejeição automática.","errorFocus":"QR_BINARY_TRUST","misconceptions":{"Sim; todo QR code é malicioso.":["QR_ALWAYS_MALICIOUS"],"Não; qualquer formulário com brasão escolar é seguro.":["BRASAO_PROVES_FORM"],"Não; preencha primeiro e pergunte depois.":["DATA_BEFORE_VERIFICATION"]},"position":5},{"id":"v5-comp-phish-review-06","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"DECIDE","contextFamily":"TEACHER_CLASSROOM_LINK","statement":"Durante a aula, a professora anuncia um link no ambiente escolar conhecido para uma atividade. Você reconhece o contexto, mas o endereço pede login novamente. O que fazer?","options":["Digitar a senha em qualquer página anunciada durante a aula.","Recusar para sempre todos os links enviados por professores.","Mandar a senha à professora para que ela faça login por você.","Conferir se o endereço pertence ao ambiente oficial e, se houver dúvida, perguntar à professora pelo próprio canal escolar antes de inserir a senha."],"correctAnswer":"Conferir se o endereço pertence ao ambiente oficial e, se houver dúvida, perguntar à professora pelo próprio canal escolar antes de inserir a senha.","explanation":"O contexto conhecido ajuda, mas não substitui conferir o destino. Um link pode ser legítimo; quando o endereço ou o novo pedido não estiver claro, confirme sem compartilhar a senha.","hint":"Use o canal escolar para confirmar, e não envie a senha a outra pessoa.","errorFocus":"CONTEXT_WITHOUT_DESTINATION_CHECK","misconceptions":{"Digitar a senha em qualquer página anunciada durante a aula.":["CLASS_CONTEXT_OVERRIDES_DOMAIN"],"Recusar para sempre todos os links enviados por professores.":["REJECT_ALL_DIGITAL_LEARNING"],"Mandar a senha à professora para que ela faça login por você.":["SEND_PASSWORD_TO_TEACHER"]},"position":6},{"id":"v5-comp-phish-review-07","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"REPORT","contextFamily":"SAFE_REPORTING","statement":"Você quer denunciar uma mensagem suspeita sem espalhar o endereço ou expor dados de alguém. Qual opção é melhor?","options":["Usar a ferramenta de denúncia da plataforma ou mostrar a mensagem a um adulto por um canal privado, sem encaminhá-la publicamente.","Publicar a captura em uma rede aberta pedindo opiniões.","Encaminhar a mensagem para todos com o endereço visível.","Responder ao remetente com dados inventados para ganhar tempo."],"correctAnswer":"Usar a ferramenta de denúncia da plataforma ou mostrar a mensagem a um adulto por um canal privado, sem encaminhá-la publicamente.","explanation":"O reporte deve reduzir o risco e preservar a privacidade. Evite ampliar a circulação da mensagem ou responder ao contato suspeito.","hint":"Escolha um caminho de denúncia que não torne a mensagem mais visível.","errorFocus":"PUBLICLY_SPREAD_SUSPICIOUS_CONTENT","misconceptions":{"Publicar a captura em uma rede aberta pedindo opiniões.":["PUBLIC_POST_EXPOSES_DATA"],"Encaminhar a mensagem para todos com o endereço visível.":["BROADCAST_REPORT"],"Responder ao remetente com dados inventados para ganhar tempo.":["ENGAGE_FOR_EVIDENCE"]},"position":7},{"id":"v5-comp-phish-review-08","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"TRANSFER","contextFamily":"ACCOUNT_BLOCK_ALERT","statement":"Um alerta diz que sua conta foi bloqueada. Como saber se existe um problema real sem depender do botão da mensagem?","options":["Clicar no botão, porque o alerta fala da sua conta.","Abrir o aplicativo ou endereço oficial por conta própria e verificar o estado da conta; pedir ajuda se aparecer algo que não reconhece.","Responder com a senha para desbloquear.","Ignorar mesmo que o aplicativo oficial confirme um problema."],"correctAnswer":"Abrir o aplicativo ou endereço oficial por conta própria e verificar o estado da conta; pedir ajuda se aparecer algo que não reconhece.","explanation":"O alerta pode ser verdadeiro ou falso. A verificação independente permite descobrir o estado real sem confiar no link recebido.","hint":"Faça a checagem no serviço, não no botão do aviso.","errorFocus":"ACCOUNT_ALERT_DEPENDENCE","misconceptions":{"Clicar no botão, porque o alerta fala da sua conta.":["MESSAGE_BUTTON_AS_ONLY_ROUTE"],"Responder com a senha para desbloquear.":["PASSWORD_UNLOCK_REQUEST"],"Ignorar mesmo que o aplicativo oficial confirme um problema.":["IGNORE_VERIFIED_ALERT"]},"position":8},{"id":"v5-comp-phish-review-09","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"JUSTIFY","contextFamily":"COMBINED_PHISHING_SIGNS","statement":"Uma mensagem inesperada usa um endereço parecido, exige resposta imediata e pede um código de acesso. Qual decisão reúne melhor os critérios estudados?","options":["Enviar o código, mas esperar para abrir o endereço.","Abrir o endereço para decidir se o pedido de código é verdadeiro.","Não enviar o código nem abrir o endereço; confirmar por um canal oficial independente e pedir ajuda a um adulto.","Concluir apenas pela aparência que a conta já foi invadida e apagar tudo."],"correctAnswer":"Não enviar o código nem abrir o endereço; confirmar por um canal oficial independente e pedir ajuda a um adulto.","explanation":"Vários sinais aumentam a necessidade de cautela, mas a mensagem não prova por si só que a conta foi invadida. Pare, preserve os segredos e verifique por outro canal.","hint":"Evite tanto obedecer quanto entrar em pânico; escolha uma conferência independente.","errorFocus":"COMBINE_SIGNS_WITHOUT_SAFE_ACTION","misconceptions":{"Enviar o código, mas esperar para abrir o endereço.":["CODE_WITHOUT_CLICK_IS_SAFE"],"Abrir o endereço para decidir se o pedido de código é verdadeiro.":["CLICK_TO_VERIFY_SECRET_REQUEST"],"Concluir apenas pela aparência que a conta já foi invadida e apagar tudo.":["PANIC_FROM_INDICATORS"]},"position":9}]'::jsonb) as item(
      id text, purpose text, difficulty text, "cognitiveProcess" text,
      "contextFamily" text, statement text, options jsonb, "correctAnswer" text,
      explanation text, hint text, "errorFocus" text, misconceptions jsonb, position integer
    )
  loop
    insert into public.learning_question_sets(scope, canonical_skill_id, purpose, version, active, metadata)
    values ('GLOBAL', v_skill_id, v_question.purpose, 5, false,
      jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', 'computing-recognize-phishing',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING', 'publication_status', 'STAGING',
        'bncc_alignment_status', 'NOT_CLAIMED'))
    on conflict (canonical_skill_id, purpose, version) where scope = 'GLOBAL' do nothing;
    select id into v_set_id from public.learning_question_sets
     where scope = 'GLOBAL' and canonical_skill_id = v_skill_id
       and purpose = v_question.purpose and version = 5
       and metadata->>'content_id' = 'computing-recognize-phishing' and active = false;
    if v_set_id is null then raise exception 'V5_CONTENT_QUESTION_SET_CONFLICT'; end if;

    select id into v_question_id from public.learning_question_bank
     where source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING' and metadata->>'content_id' = v_question.id;
    if v_question_id is null then
      insert into public.learning_question_bank(
        package_type, source_type, source_name, subject_area, domain, topic,
        statement, options, correct_answer, explanation, difficulty,
        estimated_minutes, provenance, metadata, active
      ) values (
        'TECESCOLA', 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING', 'TecEscola Question First V5 - Staging',
        'COMPUTING', 'SEGURANCA', 'phishing e verificacao de mensagens',
        v_question.statement, v_question.options, to_jsonb(v_question."correctAnswer"),
        v_question.explanation, v_question.difficulty, 2,
        'TECESCOLA_CORE_V5_AUTHORED',
        jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', v_question.id,
          'purpose', v_question.purpose, 'context_family', v_question."contextFamily",
          'cognitive_process', v_question."cognitiveProcess", 'error_focus', v_question."errorFocus",
          'remediation_hint', v_question.hint, 'misconceptions', v_question.misconceptions,
          'content_authoring_status', 'AUTHORED', 'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING',
          'publication_status', 'STAGING', 'bncc_alignment_status', 'NOT_CLAIMED'), false
      ) returning id into v_question_id;
    end if;
    if v_question_id is null then raise exception 'V5_CONTENT_QUESTION_INSERT_FAILED'; end if;
    update public.learning_question_bank set active = false
     where id = v_question_id and source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING';
    insert into public.learning_question_bank_skill_links(question_bank_id, canonical_skill_id, skill_role)
    values (v_question_id, v_skill_id, 'PRIMARY') on conflict (question_bank_id, canonical_skill_id) do nothing;
    insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
    values (v_set_id, v_question_id, v_question.position)
    on conflict (question_set_id, question_bank_id) do nothing;
  end loop;
end;
$seed_question_first_content_v5$;

